WITH flattened AS (SELECT id, host, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, attr_value), enriched AS (SELECT id, host, latency_ms, status_code, key, attr_value, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY host), 4) AS latency_ms_share, ROW_NUMBER() OVER (PARTITION BY key ORDER BY latency_ms DESC, id, key) AS seq_no, FIRST_VALUE(key) IGNORE NULLS OVER (ORDER BY latency_ms, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_key FROM flattened), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY host, key ORDER BY latency_ms DESC NULLS FIRST, id, key) AS latest_rank FROM enriched) ranked WHERE latest_rank = 1), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY host, key ORDER BY seq_no DESC NULLS LAST, id, key) AS rn FROM deduped QUALIFY rn = 1) SELECT id, latency_ms, key, attr_value, seq_no, first_known_key, rn FROM ranked ORDER BY id DESC, seq_no;
